css:
.loader { position: relative; overflow: hidden; width: var(--loader-size); height: calc(var(--loader-size) * .68); border-radius: calc(var(--loader-size) * .05); background: color-mix(in srgb, var(--loader-color) 12%, transparent); border: calc(var(--loader-size) * .01) solid color-mix(in srgb, var(--loader-color) 28%, transparent); box-sizing: border-box; }
.loader .sun { position: absolute; left: 16%; top: 18%; width: calc(var(--loader-size) * .1); height: calc(var(--loader-size) * .1); border-radius: 9999px; background: color-mix(in srgb, var(--loader-color) 55%, transparent); }
.loader .hill { position: absolute; left: 20%; bottom: 16%; width: 0; height: 0; border-left: calc(var(--loader-size) * .14) solid transparent; border-right: calc(var(--loader-size) * .14) solid transparent; border-bottom: calc(var(--loader-size) * .2) solid color-mix(in srgb, var(--loader-color) 48%, transparent); }
.loader .hill::after { content: ''; position: absolute; left: calc(var(--loader-size) * .04); bottom: calc(var(--loader-size) * -.2); border-left: calc(var(--loader-size) * .19) solid transparent; border-right: calc(var(--loader-size) * .19) solid transparent; border-bottom: calc(var(--loader-size) * .27) solid color-mix(in srgb, var(--loader-color) 34%, transparent); }
.loader .glow { position: absolute; top: 0; bottom: 0; left: 0; right: 0; background: linear-gradient(100deg, transparent 35%, color-mix(in srgb, var(--loader-color) 40%, transparent) 50%, transparent 65%); animation: twGlow calc(var(--loader-speed) * 1.7) linear infinite; }
@keyframes twGlow { 0% { transform: translateX(-100%); } 100% { transform: translateX(100%); } }
